// AI Usage Note: generated by Claude; every case checked against the saved ArtWizard API responses by running the tests.
import assert from 'node:assert/strict';
import { afterEach, beforeEach, describe, mock, test } from 'node:test';
import { Logger } from '@nestjs/common';
import { ArtWizardEventProvider, quillText } from '../../dist/infra/providers/artwizard-event-provider.js';
import type { HttpClient, HttpResponse } from '../../dist/infra/providers/http-client.js';
import type { ImportedEvent } from '../../dist/core/import/types/import.js';
import { PAGES_SAVED_AT, savedPage } from './fixtures/provider-pages.ts';

const API_KEY = 'test-api-key';

interface EventsPage {
  total: number;
  total_pages: number;
  data: Record<string, unknown>[];
}

/** A saved response of `GET /events`, parsed. */
function savedEventsPage(page: 1 | 2): EventsPage {
  return JSON.parse(savedPage(`artwizard/events-page-${page}.json`)) as EventsPage;
}

/** The saved event with this slug, from either page. */
function savedEvent(slug: string): Record<string, unknown> {
  const event = [...savedEventsPage(1).data, ...savedEventsPage(2).data].find((event) => event.slug === slug);
  assert.ok(event, slug);
  return structuredClone(event);
}

/** A saved event with its occurrences replaced by `[date_from, date_to]` pairs. */
function withOccurrences(slug: string, occurrences: [string, string][]): Record<string, unknown> {
  return {
    ...savedEvent(slug),
    event_occurrences_data: occurrences.map(([date_from, date_to]) => ({ date_from, date_to })),
  };
}

type Answer = EventsPage | { status: number; text?: string } | Error;

/**
 * An HttpClient for the events API: `pages` maps the `page` parameter to its answer. By default pages 1 and 2 are
 * the saved ones, as the last pages (the saved run had 4). Every requested URL is recorded.
 */
function apiClient(pages: Record<number, Answer> = {}): HttpClient & { requested: URL[] } {
  const answers: Record<number, Answer> = {
    1: { ...savedEventsPage(1), total_pages: 2 },
    2: { ...savedEventsPage(2), total_pages: 2 },
    ...pages,
  };
  const requested: URL[] = [];
  return {
    requested,
    get(url: string): Promise<HttpResponse> {
      requested.push(new URL(url));
      const answer = answers[Number(new URL(url).searchParams.get('page'))];
      if (answer instanceof Error) {
        return Promise.reject(answer);
      }
      if (answer === undefined) {
        return Promise.resolve({ status: 404, url, text: '' });
      }
      return Promise.resolve(
        'data' in answer
          ? { status: 200, url, text: JSON.stringify(answer) }
          : { status: answer.status, url, text: answer.text ?? '' },
      );
    },
  };
}

function makeProvider({ http = apiClient(), apiKey = API_KEY, now = PAGES_SAVED_AT } = {}) {
  return new ArtWizardEventProvider({ http, apiKey, now: () => now });
}

function normalized(raw: unknown, provider = makeProvider()): ImportedEvent {
  const result = provider.normalize(raw);
  assert.ok('event' in result, JSON.stringify(result));
  return result.event;
}

function skipReason(raw: unknown, provider = makeProvider()): string {
  const result = provider.normalize(raw);
  assert.ok('skip' in result, JSON.stringify(result));
  return result.skip.reason;
}

let logged: string[] = [];
beforeEach(() => {
  logged = [];
  mock.method(Logger.prototype, 'log', (message: unknown) => logged.push(String(message)));
});
afterEach(() => mock.restoreAll());

// FR-008, FR-015
describe('ArtWizardEventProvider.fetch', () => {
  test('requests every page of the Kyiv events that touch the catalog window, with the key', async () => {
    const http = apiClient();

    const events = await makeProvider({ http }).fetch();

    assert.equal(events.length, 40);
    assert.deepEqual(
      http.requested.map((url) => [url.origin + url.pathname, Object.fromEntries(url.searchParams)]),
      [1, 2].map((page) => [
        'https://api.artwizard.io/events',
        {
          apiKey: API_KEY,
          city: 'kyiv',
          'filter[event_occurrences_data.date_from:lte]': 'date:2026-12-01',
          'filter[event_occurrences_data.date_to:gte]': 'date:2026-11-03',
          page_size: '20',
          page: String(page),
        },
      ]),
    );
  });

  test('logs the totals, and never the key', async () => {
    await makeProvider().fetch();

    assert.deepEqual(logged, ['40 of 74 Kyiv events from 2026-11-03 to 2026-12-01, 2 pages']);
  });

  test('stops at the last page the API names', async () => {
    const http = apiClient({ 1: { ...savedEventsPage(1), total_pages: 1 } });

    const events = await makeProvider({ http }).fetch();

    assert.equal(events.length, 20);
    assert.equal(http.requested.length, 1);
  });

  test('fails the run without a key, and sends nothing', async () => {
    const http = apiClient();

    await assert.rejects(makeProvider({ http, apiKey: '' }).fetch(), /ARTWIZARD_API_KEY is not set/);
    assert.equal(http.requested.length, 0);
  });

  const failures = [
    { title: 'a page answers 401', answer: { status: 401 }, error: /page=2 answered 401$/ },
    { title: 'a page is not JSON', answer: { status: 200, text: '<html>' }, error: /is not JSON/ },
    { title: 'a page has no data', answer: { status: 200, text: '{"total":0}' }, error: /without total_pages/ },
    { title: 'a page cannot be fetched', answer: new Error(`fetch failed for ${API_KEY}`), error: /failed: fetch/ },
  ];
  for (const { title, answer, error } of failures) {
    test(`fails the run when ${title}, with the key redacted`, async () => {
      const http = apiClient({ 2: answer });

      const failure = await makeProvider({ http })
        .fetch()
        .then(() => assert.fail('fetch should fail'))
        .catch((caught: Error) => caught);

      assert.match(failure.message, error);
      assert.match(failure.message, /apiKey=REDACTED/);
      assert.ok(!failure.message.includes(API_KEY), failure.message);
    });
  }
});

describe('ArtWizardEventProvider.normalize', () => {
  test('maps a saved event with one start time to an event that lasts until the end of its day', () => {
    const event = normalized(savedEvent('santimetri-20261103'));

    assert.deepEqual(
      { ...event, description: event.description.slice(0, 40) },
      {
        externalId: 'santimetri-20261103',
        title: 'Сантиметри',
        description: event.description.slice(0, 40),
        categorySlug: 'cinema',
        venue: {
          name: 'Будинок Кіно',
          address: 'вулиця Саксаганського, 6, Київ, Київ',
          location: event.venue.location,
        },
        startsAt: '2026-11-03T16:00:00.000Z',
        endsAt: '2026-11-03T21:59:59.999Z',
        imageUrl: savedEvent('santimetri-20261103').picture_url,
        sourceUrl: 'https://artwizard.io/kyiv/e/santimetri-20261103',
      },
    );
    assert.ok(event.description.length > 0 && !event.description.includes('"insert"'));
    assert.ok(event.venue.location && event.venue.location.lat > 50 && event.venue.location.lng > 30);
  });

  test('keeps a later time on the same day as the real end', () => {
    // "День відкритих дверей": 10:30–17:30 on 4 November.
    const event = normalized(savedEvent('den-vidkritikh-dverey-20261104'));

    assert.deepEqual([event.startsAt, event.endsAt], ['2026-11-04T08:30:00.000Z', '2026-11-04T15:30:00.000Z']);
  });

  test('keeps an end after midnight as the real end', () => {
    const event = normalized(
      withOccurrences('santimetri-20261103', [['2026-11-07T22:00:00.000Z', '2026-11-08T02:00:00.000Z']]),
    );

    assert.deepEqual([event.startsAt, event.endsAt], ['2026-11-07T20:00:00.000Z', '2026-11-08T00:00:00.000Z']);
  });

  test('skips "Я бачу, вас цікавить пітьма", whose only occurrence is 00:00–23:59:59', () => {
    assert.equal(skipReason(savedEvent('ia-bachu-vas-tsikavit-pitma-20261103')), 'No start time (00:00 on ArtWizard)');
  });

  test('skips an ongoing exhibition: the opening is past, only its 00:00–23:59:59 run is in the window', () => {
    // "Іванів ковчег": opening on 20 August at 18:00, then open from 21 August to 29 November.
    assert.equal(
      skipReason(savedEvent('ivaniv-kovcheg-prostir-svobodi-20260820')),
      'No start time (00:00 on ArtWizard)',
    );
  });

  test('takes the opening of an exhibition that opens in the window, and logs the other occurrence', () => {
    // "Тимчасово постійно": opening on 5 November at 17:00, open from 5 November to 6 December.
    const event = normalized(savedEvent('timchasovo-postiyno-20261105'));

    assert.deepEqual([event.startsAt, event.endsAt], ['2026-11-05T15:00:00.000Z', '2026-11-05T21:59:59.999Z']);
    assert.deepEqual(logged, [
      'timchasovo-postiyno-20261105: 2 occurrences from 2026-11-03 to 2026-12-01; importing the one of 2026-11-05T17:00 only',
    ]);
  });

  test('takes the earliest timed occurrence in the window, whatever their order', () => {
    // "Jazz Hall Podil" lists 7, 6 and 8 November.
    const event = normalized(savedEvent('jazz-hall-podil-20261106'));

    assert.equal(event.startsAt, '2026-11-06T17:00:00.000Z');
    assert.match(logged[0] ?? '', /^jazz-hall-podil-20261106: 3 occurrences .* 2026-11-06T19:00 only$/);
  });

  test('skips an event with no occurrence in the window', () => {
    // The 2026 occurrences are past and the 2027 one is after the window.
    assert.equal(
      skipReason(savedEvent('muzichna-programa-14-18-zhovtnia-20261015')),
      'No occurrence from 2026-11-03 to 2026-12-01',
    );
  });

  test('skips an event that starts at 00:00 even with another end', () => {
    const raw = withOccurrences('santimetri-20261103', [['2026-11-05T00:00:00.000Z', '2026-11-05T02:00:00.000Z']]);

    assert.equal(skipReason(raw), 'No start time (00:00 on ArtWizard)');
  });

  test('keeps an event that starts a minute after midnight', () => {
    const raw = withOccurrences('santimetri-20261103', [['2026-11-05T00:01:00.000Z', '2026-11-05T00:01:00.000Z']]);

    assert.equal(normalized(raw).startsAt, '2026-11-04T22:01:00.000Z');
  });

  const times = [
    { title: 'in winter (UTC+2)', at: '2026-11-11T19:00:00.000Z', startsAt: '2026-11-11T17:00:00.000Z' },
    { title: 'in summer (UTC+3)', at: '2026-07-11T19:00:00.000Z', startsAt: '2026-07-11T16:00:00.000Z' },
  ];
  for (const { title, at, startsAt } of times) {
    test(`reads the time marked Z as Kyiv wall-clock time ${title}`, () => {
      const provider = makeProvider({ now: new Date(`${at.slice(0, 10)}T08:00:00Z`) });

      assert.equal(normalized(withOccurrences('santimetri-20261103', [[at, at]]), provider).startsAt, startsAt);
    });
  }

  test('points the source at the ArtWizard page, not at details_url', () => {
    const raw = { ...savedEvent('santimetri-20261103'), details_url: 'https://tickets.example/42' };

    assert.equal(normalized(raw).sourceUrl, 'https://artwizard.io/kyiv/e/santimetri-20261103');
  });

  test('takes the first type that has a category', () => {
    const raw = { ...savedEvent('santimetri-20261103'), type: ['Дітям', 'Театр', 'Кіно'] };

    assert.equal(normalized(raw).categorySlug, 'theatre');
  });

  test('skips an event whose types have no category, with the types in the reason', () => {
    const raw = { ...savedEvent('santimetri-20261103'), type: ['Дітям', 'Інше'] };

    assert.equal(skipReason(raw), 'No category for the types ["Дітям","Інше"]');
  });

  test('takes no category from a type that names an object property', () => {
    assert.match(skipReason({ ...savedEvent('santimetri-20261103'), type: ['constructor'] }), /^No category/);
  });

  test('skips an event that is not published', () => {
    assert.equal(
      skipReason({ ...savedEvent('santimetri-20261103'), status: 'draft' }),
      'Not published (status "draft")',
    );
  });

  test('skips an event outside Kyiv', () => {
    const raw = savedEvent('santimetri-20261103');
    const location = raw.location as Record<string, unknown>;
    location.city = { ...(location.city as object), slug: 'lviv', name: 'Львів' };

    assert.equal(skipReason(raw), 'Not in Kyiv (city "lviv")');
  });

  test('gives no coordinates for a venue without them', () => {
    const raw = savedEvent('santimetri-20261103');
    delete (raw.location as Record<string, unknown>).latitude;

    assert.equal(normalized(raw).venue.location, null);
  });

  test('skips a record without a slug', () => {
    const { slug: _slug, ...raw } = savedEvent('santimetri-20261103');

    assert.deepEqual(makeProvider().normalize(raw), { skip: { externalId: null, reason: 'Invalid record: slug' } });
  });

  test('skips an event without a title, naming the field', () => {
    assert.equal(skipReason({ ...savedEvent('santimetri-20261103'), title: ' ' }), 'Invalid record: title');
  });

  test('joins the inserts of a Quill description into plain text', () => {
    assert.equal(quillText('Just text, [not JSON'), 'Just text, [not JSON');
    assert.equal(quillText('[{"insert":"One "},{"insert":{"image":"x"}},{"insert":"two"}]'), 'One two');
  });
});
